contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.assume(amount > 0);
        c.init(address(0x1), address(0x2), address(0x3));
        vm.prank(address(this));
        c.newGrantProposal(recipient, amount);
        (address storedRecipient, uint256 storedAmount) = c.mapPID_grant(c.proposalCount());
        assertTrue(storedRecipient == recipient && storedAmount == amount);
